<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import PasswordInput from '@/components/PasswordInput.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import { api, errorMessage } from '@/api/client';
import type { ApiResponse } from '@/types/api';
const props=defineProps<{platform?:boolean}>();
const error=ref(''),notice=ref(''),busy=ref(false),loading=ref(true),configured=ref(false);
const settings=reactive({enabled:false,model:'openai/gpt-oss-20b',dailyRequests:100,dailyBudgetMicros:1000000,currentPassword:''});
const usage=ref<{requests:number;reservedMicros:number}|null>(null);
type Faq={id:string;question:string;answer:string;path:string;published:boolean;validUntil:string;version:number};
const faqs=ref<Faq[]>([]),selected=ref('');
const form=reactive({question:'',answer:'',path:'/help',published:false,validUntil:'',version:0});
const paths=['/register','/membership/status','/activate','/login','/services','/requests/new','/requests','/events','/announcements','/stories','/about','/contact','/help','/privacy','/terms'];
function reset(){selected.value='';Object.assign(form,{question:'',answer:'',path:'/help',published:false,validUntil:new Date(Date.now()+90*86400000).toISOString().slice(0,10),version:0});}
function edit(f:Faq){selected.value=f.id;Object.assign(form,{...f,validUntil:f.validUntil.slice(0,10)});}
async function load(){loading.value=true;error.value='';try{if(props.platform){const data=(await api.get<ApiResponse<typeof settings & {configured:boolean;usage:typeof usage.value}>>('/super-admin/chatbot')).data.data;Object.assign(settings,{enabled:data.enabled,model:data.model,dailyRequests:data.dailyRequests,dailyBudgetMicros:data.dailyBudgetMicros});configured.value=data.configured;usage.value=data.usage;}else faqs.value=(await api.get<ApiResponse<Faq[]>>('/admin/chatbot/faqs')).data.data;}catch(e){error.value=errorMessage(e);}finally{loading.value=false;}}
async function save(remove=false){busy.value=true;error.value='';notice.value='';try{if(props.platform){await api.patch('/super-admin/chatbot',settings);settings.currentPassword='';}else if(remove){await api.delete(`/admin/chatbot/faqs/${selected.value}`,{data:{version:form.version}});reset();}else{const payload={question:form.question,answer:form.answer,path:form.path,published:form.published,validUntil:new Date(form.validUntil+'T23:59:59Z').toISOString(),...(selected.value?{version:form.version}:{})};if(selected.value)await api.patch(`/admin/chatbot/faqs/${selected.value}`,payload);else await api.post('/admin/chatbot/faqs',payload);reset();}notice.value=remove?'School answer removed.':'Changes saved.';await load();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
onMounted(()=>{reset();void load();});
</script>
<template><DashboardLayout><section class="mx-auto max-w-4xl space-y-6 p-5 lg:p-10"><h1 class="text-h1">{{platform?'Chatbot settings':'School answers for the chatbot'}}</h1><ApiAlert :message="error"/><ApiAlert :message="notice" kind="success"/><p v-if="loading" role="status">Loading…</p><button v-if="error" class="secondary-button" @click="load">Reload</button>
<template v-if="platform"><p>Questions and replies are not stored. Aggregate daily usage uses UTC days. No private account lookups are available.</p><p>{{configured?'Groq key configured on server.':'Set GROQ_API_KEY in the backend environment before enabling.'}} Configuration does not prove provider connectivity.</p><form class="space-y-4 border bg-white p-6" @submit.prevent="save()"><label class="flex gap-3"><input v-model="settings.enabled" type="checkbox">Enable public assistant</label><label for="chat-model" class="field-label">Groq model</label><select id="chat-model" v-model="settings.model" class="field-input"><option value="openai/gpt-oss-20b">GPT OSS 20B — lower cost, faster</option><option value="openai/gpt-oss-120b">GPT OSS 120B — larger model</option></select><label for="daily-requests" class="field-label">Daily request limit</label><input id="daily-requests" v-model.number="settings.dailyRequests" type="number" min="1" max="10000" required class="field-input"><label for="chat-budget" class="field-label">Daily estimated budget in micro USD (1,000,000 = $1)</label><input id="chat-budget" v-model.number="settings.dailyBudgetMicros" type="number" min="1000" max="100000000" required class="field-input"><p class="text-sm">Conservative token-cost reservations include failed calls. Also set spending limits in your Groq account. Today's usage: {{usage?.requests??0}} calls; {{usage?.reservedMicros??0}} micro USD reserved.</p><label for="chat-password" class="field-label">Current password</label><PasswordInput id="chat-password" v-model="settings.currentPassword" required autocomplete="current-password"/><button class="primary-button" :disabled="busy||loading">Save chatbot settings</button></form></template>
<template v-else><p>Publish only school-approved answers. Expired answers are excluded automatically. Links must point to a public portal page; request pages require sign-in.</p><form class="space-y-4 border bg-white p-6" @submit.prevent="save()"><h2 class="text-h2">{{selected?'Edit school answer':'New school answer'}}</h2><label for="faq-question" class="field-label">Question</label><input id="faq-question" v-model.trim="form.question" required minlength="5" maxlength="180" class="field-input"><label for="faq-answer" class="field-label">Approved answer</label><textarea id="faq-answer" v-model.trim="form.answer" required minlength="5" maxlength="1800" rows="5" class="field-input"/><label for="faq-link" class="field-label">Source page</label><select id="faq-link" v-model="form.path" class="field-input"><option v-for="path in paths" :key="path" :value="path">{{path}}</option></select><label for="faq-expiry" class="field-label">Review by date (within one year)</label><input id="faq-expiry" v-model="form.validUntil" type="date" required class="field-input"><label class="flex gap-3"><input v-model="form.published" type="checkbox">Approved for public answers</label><div class="flex flex-wrap gap-3"><button class="primary-button" :disabled="busy||loading">Save answer</button><button type="button" class="secondary-button" :disabled="busy" @click="reset">New answer</button><button v-if="selected" type="button" class="secondary-button" :disabled="busy" @click="save(true)">Delete selected answer</button></div></form><p v-if="!loading&&!faqs.length">No school answers yet. Product workflow guidance is available separately.</p><article v-for="faq in faqs" :key="faq.id" class="space-y-2 border bg-white p-5"><h2 class="font-semibold">{{faq.question}}</h2><p class="whitespace-pre-wrap break-words">{{faq.answer}}</p><p>{{faq.published?'Approved':'Draft'}} · Review by {{new Date(faq.validUntil).toLocaleDateString()}}{{Date.parse(faq.validUntil)<Date.now()?' · Expired':''}}</p><button class="secondary-button" :disabled="busy" @click="edit(faq)">Edit answer</button></article></template></section></DashboardLayout></template>
